begin;
select plan(37);
insert into auth.users(id,email) values('a0000000-0000-4000-8000-000000000001','sql-owner-a@example.test'),('a0000000-0000-4000-8000-000000000002','sql-owner-b@example.test');
insert into public.profiles(owner_id,display_name,height_cm,weight_kg,goal,timezone,units)
select id,'Synthetic',175,75,'maintain','Asia/Kolkata','metric' from auth.users where id in ('a0000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000002');
insert into public.daily_logs(owner_id,local_date,timezone,weight_kg) select owner_id,'2026-03-08','America/New_York',75 from public.profiles where owner_id::text like 'a0000000%';
insert into public.plans(id,owner_id,kind) values('b0000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001','meal'),('b0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000002','workout');
insert into public.plan_versions(plan_id,owner_id,version,payload,schema_version,policy_version,prompt_version,provenance)
select id,owner_id,1,'{}','fixture','fixture','fixture','template' from public.plans where id::text like 'b0000000%';
insert into public.training_sessions(owner_id,plan_id,plan_version,started_at) select owner_id,id,1,now() from public.plans where id::text like 'b0000000%';
insert into public.ai_operations(owner_id,idempotency_key,input_digest,state,expires_at) select owner_id,gen_random_uuid(),'synthetic','pending',now()+interval '1 hour' from public.profiles where owner_id::text like 'a0000000%';
insert into public.consent_records(id,owner_id,purpose,action,policy_version) values('c0000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001','photo_storage','grant','2026-10-01'),('c0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000002','photo_storage','grant','2026-10-01');
insert into public.photo_metadata(owner_id,object_path,consent_id,expires_at) select owner_id,owner_id::text||'/synthetic.jpg',id,now()+interval '30 days' from public.consent_records where id::text like 'c0000000%';
insert into public.deletion_jobs(owner_id,state) select owner_id,'requested' from public.profiles where owner_id::text like 'a0000000%';
insert into public.usage_buckets(owner_id,bucket) select owner_id,now() from public.profiles where owner_id::text like 'a0000000%';
insert into public.ai_budget_leases(owner_id,expires_at) select owner_id,now()+interval '30 seconds' from public.profiles where owner_id::text like 'a0000000%';
select ok(exists(select 1 from cron.job where jobname='kinetra-security-cleanup'),'cleanup is scheduled');
select ok(not has_function_privilege('authenticated','public.acquire_ai_budget(uuid,integer,integer,integer,integer,integer,integer)','EXECUTE'),'budget reservation is service-only');
select ok(not has_function_privilege('anon','public.cleanup_security_records()','EXECUTE'),'anonymous cleanup denied');
select ok(not has_function_privilege('authenticated','public.cleanup_security_records()','EXECUTE'),'user cleanup denied');
select ok(has_function_privilege('service_role','public.cleanup_security_records()','EXECUTE'),'service cleanup allowed');
set local role anon;
select throws_ok('select * from public.profiles','42501','permission denied for table profiles','anonymous profiles denied');
reset role;
set local role authenticated;
set local request.jwt.claims = '{"sub":"a0000000-0000-4000-8000-000000000001","role":"authenticated"}';
select is((select count(*) from public.profiles where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'profiles: owner reads own row');
select is((select count(*) from public.profiles where owner_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'profiles: other tenant invisible');
select is((select count(*) from public.daily_logs where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'daily_logs: owner reads own row');
select is((select count(*) from public.daily_logs where owner_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'daily_logs: other tenant invisible');
select is((select count(*) from public.plans where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'plans: owner reads own row');
select is((select count(*) from public.plans where owner_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'plans: other tenant invisible');
select is((select count(*) from public.plan_versions where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'plan_versions: owner reads own row');
select is((select count(*) from public.plan_versions where owner_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'plan_versions: other tenant invisible');
select is((select count(*) from public.training_sessions where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'training_sessions: owner reads own row');
select is((select count(*) from public.training_sessions where owner_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'training_sessions: other tenant invisible');
select is((select count(*) from public.ai_operations where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'ai_operations: owner reads own row');
select is((select count(*) from public.ai_operations where owner_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'ai_operations: other tenant invisible');
select is((select count(*) from public.consent_records where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'consent_records: owner reads own row');
select is((select count(*) from public.consent_records where owner_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'consent_records: other tenant invisible');
select is((select count(*) from public.photo_metadata where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'photo_metadata: owner reads own row');
select is((select count(*) from public.photo_metadata where owner_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'photo_metadata: other tenant invisible');
select is((select count(*) from public.deletion_jobs where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'deletion_jobs: owner reads own row');
select is((select count(*) from public.deletion_jobs where owner_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'deletion_jobs: other tenant invisible');
select is((select count(*) from public.usage_buckets where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'usage_buckets: owner reads own row');
select is((select count(*) from public.usage_buckets where owner_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'usage_buckets: other tenant invisible');
select is((select count(*) from public.ai_budget_leases where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'ai_budget_leases: owner reads own row');
select is((select count(*) from public.ai_budget_leases where owner_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'ai_budget_leases: other tenant invisible');
select throws_ok($$update public.profiles set display_name='bypass'$$,'42501','permission denied for table profiles','direct update denied; revision RPC required');
reset role;
select public.configure_account_writes(false);
set local role authenticated;
select throws_ok($$select public.save_profile(1,'{}')$$,'PT403','Account writes are not enabled','direct RPC cannot bypass privacy gate');
select ok(not has_function_privilege('authenticated','public.configure_account_writes(boolean)','EXECUTE'),'user cannot enable collection');
reset role;
select ok(not (select account_writes_enabled from private.runtime_settings),'gate remains disabled');
select throws_ok($$insert into public.photo_metadata(owner_id,object_path,consent_id,expires_at) values('a0000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001/wrong.jpg','c0000000-0000-4000-8000-000000000002',now()+interval '1 day')$$,'23503',null,'photo consent cannot cross tenants');
insert into public.usage_buckets(owner_id,bucket) values('a0000000-0000-4000-8000-000000000001',now()-interval '48 hours');
insert into public.ai_budget_leases(owner_id,expires_at) values('a0000000-0000-4000-8000-000000000001',now()-interval '1 hour');
insert into public.ai_operations(owner_id,idempotency_key,input_digest,state,expires_at) values('a0000000-0000-4000-8000-000000000001',gen_random_uuid(),'expired-fixture','failed',now()-interval '1 hour');
select public.cleanup_security_records();
select is((select count(*) from public.usage_buckets where owner_id='a0000000-0000-4000-8000-000000000001' and bucket < now()-interval '24 hours'),0::bigint,'expired buckets removed');
select is((select count(*) from public.ai_budget_leases where owner_id='a0000000-0000-4000-8000-000000000001' and expires_at < now()),0::bigint,'expired leases removed');
select is((select count(*) from public.ai_operations where owner_id='a0000000-0000-4000-8000-000000000001' and expires_at < now()),0::bigint,'expired operations removed');
select is((select count(*) from public.profiles where owner_id='a0000000-0000-4000-8000-000000000001'),1::bigint,'cleanup preserves profile data');
select * from finish();
rollback;
